class Solution {
    private int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
    public List<String> findWords(char[][] board, String[] words) {
        int[][] trie = new int[words.length * 11 + 1][26];
        String[] endWord = new String[trie.length];
        int size = 1;
        for (String w : words) {
            int node = 0;
            for (char c : w.toCharArray()) {
                int idx = c - 'a';
                if (trie[node][idx] == 0) trie[node][idx] = size++;
                node = trie[node][idx];
            }
            endWord[node] = w;
        }
        List<String> result = new java.util.ArrayList<>();
        int m = board.length, n = board[0].length;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                dfs(board, i, j, 0, trie, endWord, result);
        return result;
    }
    private void dfs(char[][] board, int r, int c, int node, int[][] trie, String[] endWord, List<String> result) {
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length || board[r][c] == '#') return;
        int idx = board[r][c] - 'a';
        if (trie[node][idx] == 0) return;
        node = trie[node][idx];
        if (endWord[node] != null) { result.add(endWord[node]); endWord[node] = null; }
        char tmp = board[r][c];
        board[r][c] = '#';
        for (int[] d : dirs) dfs(board, r + d[0], c + d[1], node, trie, endWord, result);
        board[r][c] = tmp;
    }
}

import java.util.*;

class Solution {
    public List<String> findWords(char[][] board, String[] words) {
        List<String> result = new ArrayList<>();
        int[] root = new int[27];
        int[][] children = new int[words.length * 11 + 1][27];
        int nodeCount = 1;
        for (String word : words) {
            int[] node = root;
            for (int ci = 0; ci < word.length(); ci++) {
                int c = word.charAt(ci) - 'a';
                if (node[c] == 0) {
                    node[c] = nodeCount++;
                }
                node = children[node[c]];
            }
            node[26] = 1;
        }
        Map<Integer, String> nodeWords = new HashMap<>();
        for (String word : words) {
            int[] node = root;
            for (int ci = 0; ci < word.length(); ci++) {
                node = children[node[word.charAt(ci) - 'a']];
            }
        }
        int m = board.length, n = board[0].length;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                dfs(board, i, j, root, children, new StringBuilder(), result);
            }
        }
        return result;
    }
    private void dfs(char[][] board, int r, int c, int[] node, int[][] children, StringBuilder sb, List<String> result) {
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length || board[r][c] == '#') return;
        char ch = board[r][c];
        int idx = ch - 'a';
        if (node[idx] == 0) return;
        int[] child = children[node[idx]];
        sb.append(ch);
        if (child[26] == 1) {
            result.add(sb.toString());
            child[26] = 0;
        }
        board[r][c] = '#';
        dfs(board, r + 1, c, child, children, sb, result);
        dfs(board, r - 1, c, child, children, sb, result);
        dfs(board, r, c + 1, child, children, sb, result);
        dfs(board, r, c - 1, child, children, sb, result);
        board[r][c] = ch;
        sb.deleteCharAt(sb.length() - 1);
    }
}
